SET lock_timeout = '5s';
SET statement_timeout = '60s';

-- Catalog Read Model phase 2b: the measurement tables take the names
-- scientists read them by. Hand-authored on purpose: pg-delta has no rename
-- and would express this as DROP + CREATE, which loses every row. Everything
-- here is a catalog rename (ALTER ... RENAME), so no data moves and every
-- dependent object (views, policies, FKs, triggers, column defaults) follows
-- by OID. Function bodies and comments are text and cannot follow; the
-- companion migration generated by `declarative sync` right after this one
-- re-creates them against the new names.
--
--   spectrum_line_fits       -> line_fits         (the fit run: provenance)
--   spectrum_lines           -> lines             (one row per spectrum x line)
--   object_photometry        -> catalog_matches   (the cross-match: provenance)
--   object_photometry_bands  -> photometry        (one row per match x band)
--   photometry.photometry_id -> match_id
--   dr_spectrum_lines        -> dr_lines
--   dr_photometry            -> dr_catalog_matches
--   dr_photometry_bands      -> dr_photometry
--   cat_spectrum_lines       -> cat_lines
--   cat_photometry           -> cat_catalog_matches
--   cat_photometry_bands     -> cat_photometry
--   spectrum_line_fits_status -> line_fits_status
--
-- Order matters where a new name is an old one: the frozen and catalog
-- "photometry" names move to catalog_matches before the bands tables take
-- them. The API contract is untouched: sync stream names, the release count
-- keys and the RPC signatures keep their names.

-- Tables and the sequence
ALTER TABLE public.spectrum_line_fits RENAME TO line_fits;
ALTER TABLE public.spectrum_lines RENAME TO lines;
ALTER TABLE public.object_photometry RENAME TO catalog_matches;
ALTER TABLE public.object_photometry_bands RENAME TO photometry;
ALTER TABLE public.dr_spectrum_lines RENAME TO dr_lines;
ALTER TABLE public.dr_photometry RENAME TO dr_catalog_matches;
ALTER TABLE public.dr_photometry_bands RENAME TO dr_photometry;
ALTER TABLE public.photometry RENAME COLUMN photometry_id TO match_id;
ALTER TABLE public.dr_photometry RENAME COLUMN photometry_id TO match_id;
ALTER SEQUENCE public.object_photometry_id_seq RENAME TO catalog_matches_id_seq;

-- Views (definitions follow the tables by OID; only the names and the one
-- projected column change)
ALTER VIEW public.spectrum_line_fits_status RENAME TO line_fits_status;
ALTER VIEW public.cat_spectrum_lines RENAME TO cat_lines;
ALTER VIEW public.cat_photometry RENAME TO cat_catalog_matches;
ALTER VIEW public.cat_photometry_bands RENAME TO cat_photometry;
ALTER VIEW public.cat_photometry RENAME COLUMN photometry_id TO match_id;

-- Constraints (a PRIMARY KEY / UNIQUE rename renames its index too)
ALTER TABLE public.line_fits RENAME CONSTRAINT spectrum_line_fits_pkey TO line_fits_pkey;
ALTER TABLE public.line_fits RENAME CONSTRAINT spectrum_line_fits_spectrum_id_fkey TO line_fits_spectrum_id_fkey;
ALTER TABLE public.line_fits RENAME CONSTRAINT spectrum_line_fits_z_source_check TO line_fits_z_source_check;
ALTER TABLE public.line_fits RENAME CONSTRAINT spectrum_line_fits_z_quality_check TO line_fits_z_quality_check;
ALTER TABLE public.line_fits RENAME CONSTRAINT spectrum_line_fits_spectrum_science_hash_check TO line_fits_spectrum_science_hash_check;
ALTER TABLE public.lines RENAME CONSTRAINT spectrum_lines_pkey TO lines_pkey;
ALTER TABLE public.lines RENAME CONSTRAINT spectrum_lines_spectrum_id_fkey TO lines_spectrum_id_fkey;
ALTER TABLE public.lines RENAME CONSTRAINT spectrum_lines_object_id_fkey TO lines_object_id_fkey;
ALTER TABLE public.catalog_matches RENAME CONSTRAINT object_photometry_pkey TO catalog_matches_pkey;
ALTER TABLE public.catalog_matches RENAME CONSTRAINT object_photometry_object_id_fkey TO catalog_matches_object_id_fkey;
ALTER TABLE public.catalog_matches RENAME CONSTRAINT object_photometry_field_catalog_name_catalog_id_key TO catalog_matches_field_catalog_name_catalog_id_key;
ALTER TABLE public.photometry RENAME CONSTRAINT object_photometry_bands_pkey TO photometry_pkey;
ALTER TABLE public.photometry RENAME CONSTRAINT object_photometry_bands_photometry_id_fkey TO photometry_match_id_fkey;
ALTER TABLE public.photometry RENAME CONSTRAINT object_photometry_bands_object_id_fkey TO photometry_object_id_fkey;
ALTER TABLE public.dr_lines RENAME CONSTRAINT dr_spectrum_lines_pkey TO dr_lines_pkey;
ALTER TABLE public.dr_catalog_matches RENAME CONSTRAINT dr_photometry_pkey TO dr_catalog_matches_pkey;
ALTER TABLE public.dr_photometry RENAME CONSTRAINT dr_photometry_bands_pkey TO dr_photometry_pkey;

-- Indexes
ALTER INDEX public.idx_spectrum_lines_line_snr RENAME TO idx_lines_line_snr;
ALTER INDEX public.idx_spectrum_lines_object_id_line RENAME TO idx_lines_object_id_line;
ALTER INDEX public.idx_spectrum_line_fits_updated_at RENAME TO idx_line_fits_updated_at;
ALTER INDEX public.idx_spectrum_line_fits_target_id RENAME TO idx_line_fits_target_id;
ALTER INDEX public.idx_spectrum_line_fits_program_slug RENAME TO idx_line_fits_program_slug;
ALTER INDEX public.idx_spectrum_line_fits_observation RENAME TO idx_line_fits_observation;
ALTER INDEX public.idx_object_photometry_object_id RENAME TO idx_catalog_matches_object_id;
ALTER INDEX public.idx_object_photometry_field RENAME TO idx_catalog_matches_field;
ALTER INDEX public.idx_object_photometry_bands_object_id_band RENAME TO idx_photometry_object_id_band;
ALTER INDEX public.idx_object_photometry_bands_band_snr RENAME TO idx_photometry_band_snr;
ALTER INDEX public.idx_object_photometry_bands_band_mag RENAME TO idx_photometry_band_mag;
ALTER INDEX public.idx_dr_spectrum_lines_tag_line_snr RENAME TO idx_dr_lines_tag_line_snr;
ALTER INDEX public.idx_dr_photometry_tag_object RENAME TO idx_dr_catalog_matches_tag_object;
ALTER INDEX public.idx_dr_photometry_tag_field_catalog RENAME TO idx_dr_catalog_matches_tag_field_catalog;
ALTER INDEX public.idx_dr_photometry_bands_tag_band_snr RENAME TO idx_dr_photometry_tag_band_snr;
ALTER INDEX public.idx_dr_photometry_bands_tag_band_mag RENAME TO idx_dr_photometry_tag_band_mag;

-- Trigger functions and triggers
ALTER FUNCTION public.sync_spectrum_lines() RENAME TO sync_lines;
ALTER FUNCTION public.sync_object_photometry_bands() RENAME TO sync_photometry;
ALTER FUNCTION public.relink_bands_from_photometry() RENAME TO relink_photometry_from_matches;
ALTER TRIGGER sync_spectrum_lines_trigger ON public.line_fits RENAME TO sync_lines_trigger;
ALTER TRIGGER bump_spectrum_line_fits_updated_at_trigger ON public.line_fits RENAME TO bump_line_fits_updated_at_trigger;
ALTER TRIGGER sync_object_photometry_bands_trigger ON public.catalog_matches RENAME TO sync_photometry_trigger;
ALTER TRIGGER relink_bands_from_photometry_trigger ON public.catalog_matches RENAME TO relink_photometry_from_matches_trigger;

-- Policies
ALTER POLICY select_spectrum_line_fits_by_spectrum ON public.line_fits RENAME TO select_line_fits_by_spectrum;
ALTER POLICY admin_insert_spectrum_line_fits ON public.line_fits RENAME TO admin_insert_line_fits;
ALTER POLICY admin_update_spectrum_line_fits ON public.line_fits RENAME TO admin_update_line_fits;
ALTER POLICY admin_delete_spectrum_line_fits ON public.line_fits RENAME TO admin_delete_line_fits;
ALTER POLICY select_spectrum_lines_by_spectrum ON public.lines RENAME TO select_lines_by_spectrum;
ALTER POLICY admin_insert_spectrum_lines ON public.lines RENAME TO admin_insert_lines;
ALTER POLICY admin_update_spectrum_lines ON public.lines RENAME TO admin_update_lines;
ALTER POLICY admin_delete_spectrum_lines ON public.lines RENAME TO admin_delete_lines;
ALTER POLICY select_object_photometry_by_access ON public.catalog_matches RENAME TO select_catalog_matches_by_access;
ALTER POLICY admin_object_photometry_insert ON public.catalog_matches RENAME TO admin_catalog_matches_insert;
ALTER POLICY admin_object_photometry_update ON public.catalog_matches RENAME TO admin_catalog_matches_update;
ALTER POLICY admin_object_photometry_delete ON public.catalog_matches RENAME TO admin_catalog_matches_delete;
ALTER POLICY select_object_photometry_bands_by_parent ON public.photometry RENAME TO select_photometry_by_parent;
ALTER POLICY admin_object_photometry_bands_insert ON public.photometry RENAME TO admin_photometry_insert;
ALTER POLICY admin_object_photometry_bands_update ON public.photometry RENAME TO admin_photometry_update;
ALTER POLICY admin_object_photometry_bands_delete ON public.photometry RENAME TO admin_photometry_delete;
ALTER POLICY select_dr_spectrum_lines ON public.dr_lines RENAME TO select_dr_lines;
ALTER POLICY select_dr_photometry ON public.dr_catalog_matches RENAME TO select_dr_catalog_matches;
ALTER POLICY select_dr_photometry_bands ON public.dr_photometry RENAME TO select_dr_photometry;

-- Production carries a hand-made pg_cron job, weekly-analyze, that is not in
-- the repository (created on the hosted project, carried over by
-- ops/scripts/dump-hosted.sh) and names object_photometry. Point it at the
-- new name where the job exists; a no-op everywhere else (no pg_cron, or no
-- such job). EXECUTE keeps the block compilable where the cron schema is
-- absent.
DO $$
DECLARE
  v_jobid bigint;
BEGIN
  IF EXISTS (SELECT 1 FROM pg_extension WHERE extname = 'pg_cron') THEN
    EXECUTE 'SELECT jobid FROM cron.job WHERE jobname = $1' INTO v_jobid USING 'weekly-analyze';
    IF v_jobid IS NOT NULL THEN
      EXECUTE 'SELECT cron.alter_job($1, command := $2)'
        USING v_jobid, 'ANALYZE targets; ANALYZE spectra; ANALYZE objects; ANALYZE shutters; ANALYZE catalog_matches;';
    END IF;
  END IF;
END $$;
